/* Квадратные, биквадратные и сводимые к ним уравнения — 20 задач. */
for(let v=0;v<5;v++){
 const u=1+2*v,w=5+4*v;
 const r=2+v,s=-1-v;
 add('quadratic','Разность квадратов · вариант '+(v+1),
  '(4x + '+u+')² = (2x + '+w+')². Найди больший корень.',
  r,
  ['Перенеси квадраты в одну часть и разложи разность квадратов.','Реши оба линейных уравнения, возникающих из произведения.'],
  ['Пусть A = 4x + '+u+', B = 2x + '+w+'. Тогда A² − B² = (A − B)(A + B) = 0.',
   'Из A − B = 0 получаем 2x − '+(4+2*v)+' = 0, то есть x = '+r+'. Из A + B = 0 получаем 6x + '+(6+6*v)+' = 0, то есть x = '+s+'.',
   'Корни '+r+' и '+s+'. Больший корень: '+r+'. Подстановка в исходное равенство подтверждает оба корня.'],
  'Используй разложение A²−B²=(A−B)(A+B).',
  'Оба линейных множителя дают корни '+r+' и '+s+'.',
  'При извлечении корня нельзя оставить только случай A=B: возможен и случай A=−B.');
}
for(let v=0;v<5;v++){
 const r=v+2,s=-(v+1),product=(v+1)*(v+2);
 add('quadratic','Квадратное уравнение · вариант '+(v+1),
  'Реши x² − x − '+product+' = 0. Укажи больший корень.',
  r,
  ['Найди два числа с произведением −'+product+' и суммой 1.','Либо вычисли дискриминант и проверь оба знака корня.'],
  ['Дискриминант D = 1 + 4 · '+product+' = '+(2*v+3)+'².',
   'Корни равны (1 ± '+(2*v+3)+')/2, то есть '+r+' и '+s+'.',
   'Больший корень — '+r+'. Подстановка даёт '+(r*r-r-product)+' = 0.'],
  'Используй дискриминант или подбери целые корни по сумме и произведению.',
  'Сумма корней равна 1, произведение равняется −'+product+'.',
  'Не теряй отрицательный корень, когда выбираешь больший.');
}
for(let v=0;v<5;v++){
 const a=v+1,b=v+3,answer=a*b,coef=a*a+b*b;
 add('quadratic','Биквадратное уравнение · вариант '+(v+1),
  'Реши x⁴ − '+coef+'x² + '+(a*a*b*b)+' = 0. Найди произведение положительных корней.',
  answer,
  ['Сделай замену t = x².','Разложи полученное квадратное уравнение на множители.'],
  ['Положим t = x². Тогда t² − '+coef+'t + '+(a*a*b*b)+' = (t − '+(a*a)+')(t − '+(b*b)+') = 0.',
   'Следовательно, x² = '+(a*a)+' или x² = '+(b*b)+'. Положительные корни исходного уравнения: '+a+' и '+b+'.',
   'Их произведение равно '+a+' · '+b+' = '+answer+'.'],
  'Сведи уравнение четвёртой степени к квадратному относительно x².',
  'Решения x² равны '+(a*a)+' и '+(b*b)+', значит положительные x равны '+a+' и '+b+'.',
  'После замены t=x² учитывай только t≥0, а в исходном уравнении сохраняй оба знака x.');
}
for(let v=0;v<5;v++){
 const r=2+5*v,s=1+5*v,greater=4+5*v,other=(8+25*v)/5;
 add('quadratic','Квадраты линейных выражений · вариант '+(v+1),
  'Реши 9(x − '+r+')² = 4(x − '+s+')². Укажи больший корень.',
  greater,
  ['После извлечения квадратного корня рассмотри два знака.','Каждый знак даёт отдельное линейное уравнение.'],
  ['Из равенства квадратов следуют два случая: 3(x − '+r+') = 2(x − '+s+') и 3(x − '+r+') = −2(x − '+s+').',
   'Первый случай даёт x = 3·'+r+' − 2·'+s+' = '+greater+'. Второй даёт 5x = 3·'+r+' + 2·'+s+', то есть x = '+other+'.',
   'Так как '+greater+' > '+other+', больший корень равен '+greater+'.'],
  'При извлечении квадратного корня обязательно учитывай знаки «плюс» и «минус».',
  'Подстановка каждого найденного значения сохраняет исходное равенство квадратов.',
  'Нельзя заменить равенство квадратов равенством самих выражений без второго случая.');
}

/* Рациональные уравнения с ОДЗ и аккуратной проверкой — 10 задач. */
for(let v=0;v<5;v++){
 const a=v+2,b=v+1,c=3*v+5,x=2*v+4;
 add('rational','Сокращение дроби и ОДЗ · вариант '+(v+1),
  'Реши ((x − '+a+')(x + '+b+'))/(x − '+a+') = '+c+'.',
  x,
  ['Сначала запиши ОДЗ исходного уравнения.','Сокращать множитель можно только при условии, что он не равен нулю.'],
  ['Знаменатель требует x ≠ '+a+'. При этом ограничении дробь сокращается: x + '+b+' = '+c+'.',
   'Отсюда x = '+c+' − '+b+' = '+x+'.',
   'Найденное значение не равно запрещённому '+a+', значит единственный корень — '+x+'.'],
  'Выпиши ограничение на знаменатель до сокращения дроби.',
  'x='+x+' допустим, поскольку '+x+' ≠ '+a+'.',
  'Сокращение не возвращает запрещённое значение x='+a+' в область допустимых значений.');
}
for(let v=0;v<5;v++){
 const a=v+2,k=v+1,sum=2*k;
 add('rational','Сумма корней рационального уравнения · вариант '+(v+1),
  'Уравнение 1/(x − '+a+') + 1/(x + '+a+') = 1/'+k+' имеет два действительных корня. Найди их сумму.',
  sum,
  ['ОДЗ: x ≠ ±'+a+'. Приведи дроби к общему знаменателю.','После умножения на знаменатель примени теорему Виета.'],
  ['ОДЗ: x ≠ '+a+' и x ≠ −'+a+'. Левая часть равна 2x/(x² − '+(a*a)+').',
   'Умножаем на знаменатель: x² − '+sum+'x − '+(a*a)+' = 0. По теореме Виета сумма корней равна '+sum+'.',
   'Дискриминант положителен, а x=±'+a+' не обращают полученный многочлен в ноль. Оба корня допустимы, их сумма — '+sum+'.'],
  'Сведи уравнение к квадратному и используй сумму корней.',
  'Для x²−'+sum+'x−'+(a*a)+'=0 сумма корней равна '+sum+'.',
  'Проверь запрещённые значения ±'+a+' после умножения на знаменатель.');
}

/* Иррациональные уравнения — 10 задач. */
for(let v=0;v<5;v++){
 const root=v+3,other=v,shift=1-v,right=v+1;
 add('irrational','Посторонний корень после возведения в квадрат · вариант '+(v+1),
  'Реши √(x + '+shift+') = x − '+right+'.',
  root,
  ['Правая часть должна быть неотрицательной: x ≥ '+right+'.','После возведения в квадрат обязательно вернись к исходному уравнению.'],
  ['ОДЗ с учётом знака правой части: x ≥ '+right+'. После возведения в квадрат получаем x + '+shift+' = (x − '+right+')².',
   'После упрощения: (x − '+other+')(x − '+root+') = 0. Кандидаты: x='+other+' и x='+root+'.',
   'x='+other+' не удовлетворяет условию x≥'+right+'. Для x='+root+' обе части равны 2, значит ответ: '+root+'.'],
  'До возведения в квадрат потребуй, чтобы правая часть была неотрицательной.',
  'Корень x='+root+' проходит исходную проверку; x='+other+' исключается по ОДЗ.',
  'Возведение в квадрат может добавить корень, у которого правая часть отрицательна.');
}
for(let v=0;v<5;v++){
 const r=v+1,t=v+2,u=v+1,a=t*t-r,b=u*u-r,answer=r,total=t+u;
 add('irrational','Сумма двух корней · вариант '+(v+1),
  'Реши √(x + '+a+') + √(x + '+b+') = '+total+'.',
  answer,
  ['Обозначь корни через U и V и используй их сумму.','Вычти квадраты: U²−V²=(U−V)(U+V).'],
  ['Пусть U=√(x+'+a+'), V=√(x+'+b+'). Тогда U+V='+total+', а U²−V²='+ (a-b) +'.',
   'По формуле разности квадратов U−V=('+ (a-b) +')/'+total+'='+ (t-u) +'. Решаем систему U+V='+total+', U−V='+(t-u)+': получаем U='+t+', V='+u+'.',
   'Из U²=x+'+a+' следует x='+ (t*t-a) +'='+answer+'. Оба корня неотрицательны, поэтому решение допустимо.'],
  'Используй одновременно сумму корней и разность их квадратов.',
  'Получаются значения подкоренных выражений '+(t*t)+' и '+(u*u)+', которые дают исходную сумму '+total+'.',
  'Не возводи сумму двух корней в квадрат, теряя смешанное слагаемое 2UV.');
}

/* Показательные уравнения — 10 задач. */
for(let v=0;v<5;v++){
 const answer=v-2,rhs=3*v+2;
 add('exponential','Общее основание степени · вариант '+(v+1),
  'Реши 4^(x − '+v+') · 8^('+(2*v)+' − x) = 2^('+rhs+').',
  answer,
  ['Представь 4 и 8 как степени двойки.','При равных положительных основаниях приравняй показатели.'],
  ['Перепишем левую часть как 2^[2(x−'+v+') + 3('+ (2*v) +'−x)].',
   'Показатель равен 4'+v+'−x. Поэтому 4'+v+'−x='+rhs+'.',
   'Отсюда x='+answer+'. Подстановка даёт показатель '+rhs+' в обеих частях.'],
  'Приведи все степени к основанию 2.',
  'Линейное уравнение показателей даёт x='+answer+'.',
  'При умножении степеней складываются показатели, а при возведении степени в степень они перемножаются.');
}
for(let v=0;v<5;v++){
 const base=2+(v%3),m=v+1,n=m+2,coef=Math.pow(base,m)+Math.pow(base,n),constant=Math.pow(base,m+n),answer=m+n;
 add('exponential','Замена переменной t = aˣ · вариант '+(v+1),
  'Найди сумму всех действительных корней уравнения '+base+'^(2x) − '+coef+'·'+base+'^x + '+constant+' = 0.',
  answer,
  ['Положи t='+base+'^x; для любого x значение t положительно.','Разложи квадратный трёхчлен по корням.'],
  ['Пусть t='+base+'^x>0. Получаем t² − ('+Math.pow(base,m)+'+'+Math.pow(base,n)+')t + '+constant+'=0.',
   'Трёхчлен раскладывается в ('+base+'^x−'+Math.pow(base,m)+')('+base+'^x−'+Math.pow(base,n)+')=0. Следовательно, x='+m+' или x='+n+'.',
   'Сумма двух действительных корней равна '+m+'+'+n+'='+answer+'.'],
  'Сведи показательное уравнение к квадратному относительно положительного t='+base+'^x.',
  'Поскольку основание '+base+' больше 1, равенства '+base+'^x='+Math.pow(base,m)+' и '+base+'^x='+Math.pow(base,n)+' дают x='+m+' и x='+n+'.',
  'Не рассматривай отрицательные значения t: показательную степень нельзя приравнять к неположительному числу.');
}

/* Логарифмические уравнения и ОДЗ — 10 задач. */
for(let v=0;v<5;v++){
 const m=v+1,u=Math.pow(2,m),w=4,r=10+v,p=r-u,q=w-r,other=r-u-w;
 add('logarithmic','Логарифмы с общим основанием · вариант '+(v+1),
  'Реши log₂(x − '+p+') + log₂(x − '+(r-w)+') = '+(m+2)+'.',
  r,
  ['ОДЗ требует положительности обоих аргументов логарифмов.','Объедини сумму логарифмов в логарифм произведения, затем проверь оба корня.'],
  ['ОДЗ: x>'+p+' и x>'+(-q)+'. Объединяем логарифмы: (x−('+p+'))(x+('+q+'))=2^'+(m+2)+'='+u*w+'.',
   'Полученное квадратное уравнение имеет корни x='+r+' и x='+other+'. Второй корень меньше '+p+' и нарушает ОДЗ.',
   'x='+r+' допустим: аргументы равны '+u+' и '+w+'. Ответ: '+r+'.'],
  'Сначала выпиши ОДЗ, затем используй свойство суммы логарифмов.',
  'При x='+r+' аргументы положительны, а их произведение равно 2^'+(m+2)+'.',
  'После объединения логарифмов проверяй каждый корень на положительность обоих аргументов.');
}
for(let v=0;v<5;v++){
 const m=v+1,answer=Math.pow(2,2*m),rhs=3*m;
 add('logarithmic','Логарифмы с разными основаниями · вариант '+(v+1),
  'Реши log₂x + log₄x = '+rhs+'.',
  answer,
  ['Замени log₄x через логарифм по основанию 2.','Выпиши условие x>0.'],
  ['ОДЗ: x>0. Положим y=log₂x. Так как 4=2², log₄x=y/2.',
   'Получаем y+y/2='+rhs+', откуда y='+(2*m)+'.',
   'Следовательно, x=2^'+(2*m)+'='+answer+'. Проверка: log₂x='+(2*m)+', log₄x='+m+'.'],
  'Приведи логарифмы к одному основанию.',
  'Значения логарифмов '+(2*m)+' и '+m+' дают сумму '+rhs+'.',
  'При замене основания log₄x равен половине log₂x, а не удвоенному значению.');
}

