/* Алгебраические и тригонометрические системы — 20 задач. */
for(let v=0;v<3;v++){
 const r=v+3,s=2*v+1,sum=r+s,diff=2*r-s;
 add('systems','Линейная система с исключением · вариант '+(v+1),
  'Реши систему: { x + y = '+sum+'; 2x − y = '+diff+' }. Найди x.',
  r,
  ['Сложи уравнения так, чтобы y уничтожился.','После нахождения x подставь его в первое уравнение.'],
  ['Складываем уравнения: 3x = '+sum+' + ('+diff+') = '+(3*r)+'.',
   'Значит x='+r+'. Из x+y='+sum+' получаем y='+s+'.',
   'Пара ('+r+'; '+s+') удовлетворяет обоим уравнениям, поэтому ответ x='+r+'.'],
  'Примени метод сложения, уничтожив неизвестную y.',
  'Подстановка пары ('+r+';'+s+') даёт '+sum+' и '+diff+'.',
  'При сложении учитывай знак −y во втором уравнении.');
}
for(let v=0;v<3;v++){
 const r=v+2,s=v+5,sum=r+s,product=r*s,answer=r*r+s*s;
 add('systems','Симметричная система · сумма квадратов, вариант '+(v+1),
  'Для системы { x + y = '+sum+'; xy = '+product+' } найди x² + y².',
  answer,
  ['Возведи равенство x+y='+sum+' в квадрат.','Используй формулу (x+y)²=x²+2xy+y².'],
  ['Из (x+y)²=x²+2xy+y² следует x²+y²=(x+y)²−2xy.',
   'Подставляем данные системы: x²+y²='+sum+'²−2·'+product+'.',
   'Получаем '+(sum*sum)+'−'+(2*product)+'='+answer+'.'],
  'Вырази сумму квадратов через сумму и произведение корней.',
  'Формула x²+y²=(x+y)²−2xy даёт '+answer+'.',
  'Не забывай множитель 2 перед произведением xy.');
}
for(let v=0;v<3;v++){
 const r=v+5,s=2,diff=r-s,product=r*s,answer=diff*diff+2*product;
 add('systems','Разность и произведение · вариант '+(v+1),
  'Для системы { x − y = '+diff+'; xy = '+product+' } найди x² + y².',
  answer,
  ['Возведи в квадрат разность x−y.','Сопоставь (x−y)² с x²+y²−2xy.'],
  ['Раскрываем квадрат: (x−y)²=x²−2xy+y².',
   'Следовательно, x²+y²=(x−y)²+2xy='+diff+'²+2·'+product+'.',
   'Искомое значение равно '+answer+'.'],
  'Используй тождество x²+y²=(x−y)²+2xy.',
  'Подстановка известных разности и произведения даёт '+answer+'.',
  'В формуле для квадрата разности средний член равен −2xy.');
}
for(let v=0;v<3;v++){
 const r=v+1,s=v+4,sum=r+s,squares=r*r+s*s,answer=r*s;
 add('systems','Сумма и сумма квадратов · вариант '+(v+1),
  'В системе { x + y = '+sum+'; x² + y² = '+squares+' } найди xy.',
  answer,
  ['Возведи сумму x+y в квадрат.','Вырази 2xy как разность известных величин.'],
  ['По формуле (x+y)²=x²+y²+2xy.',
   'Отсюда 2xy='+sum+'²−'+squares+'='+(sum*sum-squares)+'.',
   'Следовательно, xy='+(sum*sum-squares)+'/2='+answer+'.'],
  'Свяжи квадрат суммы с суммой квадратов и произведением.',
  'Подстановка пары x='+r+', y='+s+' подтверждает значение xy='+answer+'.',
  'Не дели на 2 раньше, чем вычислишь разность.');
}

